[" Here's an outline for a simple login page implementation using Flask, a popular Python web framework. This example assumes you have a User model with `email`, `password` and other necessary attributes.

```python
from flask import Flask, render_template, redirect, url_for, request, flash
from flask_sqlalchemy import SQLAlchemy
from flask_login import LoginManager, UserMixin, login_user, logout_user, login_required, current_user
from werkzeug.security import generate_password_hash, check_password_hash
import os

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///users.db'
app.secret_key = os.urandom(24)
db = SQLAlchemy(app)
login_manager = LoginManager()
login_manager.init_app(app)

# User model, define the User class here
# Add appropriate methods for checking if user's email is already registered and updating their email

@app.route('/')
def login():
    return render_template('login.html')

@app.route('/change_email', methods=['GET', 'POST'])
@login_required
def change_email():
    if request.method == 'POST':
        old_email = request.form['old_email']
        new_email = request.form['new_email']
        confirm_password = request.form['confirm_password']
        password = request.form['password']

        user = User.query.filter_by(email=current_user.email).first()

        if not user:
            flash('Invalid account')
            return redirect(url_for('login'))

        if old_email != current_user.email or new_email == current_user.email:
            flash('Old email and new email must be different')
            return redirect(url_for('change_email'))

        if not check_password_hash(user.password, password):
            flash('Password is incorrect')
            return redirect(url_for('change_email'))

        if confirm_password != new_email:
            flash('Password confirmation does not match')
