typedef unsigned long long ull;

void read_and_save(const char *input_file, const char *output_file) {
    FILE *input = fopen(input_file, "rb");
    if (!input) {
        fprintf(stderr, "Error: cannot open file %s\n", input_file);
        return;
    }

    FILE *output = fopen(output_file, "w");
    if (!output) {
        fprintf(stderr, "Error: cannot create file %s\n", output_file);
        fclose(input);
        return;
    }

    char buffer[4096];
    ull bytes_read = 0;
    ull checksum = 0;

    while (!feof(input)) {
        size_t n = fread(buffer, sizeof(char), sizeof(buffer), input);
        if (n > 0) {
            bytes_read += n;
            checksum ^= *(ull*)buffer; // XOR the checksum with the contents of buffer
        }
    }

    fprintf(output, "bytes_read: %llu\nchecksum: %llu\n", bytes_read, checksum);

    fclose(input);
    fclose(output);
}

int main() {
    const char *input_file = "input.txt";
    const char *output_file = "output.txt";

    read_and_save(input_file, output_file);

    return 0;
}
