[' Here is a simple C code that implements your requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

typedef unsigned int uint32_t;

uint32_t calculateChecksum(const void *buffer, size_t length) {
    const uint8_t *buf = (const uint8_t *)buffer;
    uint32_t checksum = 0;
    for (size_t i = 0; i < length; ++i)
        checksum += buf[i];
    return checksum;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s input_file output_file\n", argv[0]);
        exit(1);
    }

    int fd_input = open(argv[1], O_RDONLY);
    if (fd_input == -1) {
        perror("open");
        exit(1);
    }

    struct stat file_stat;
    if (fstat(fd_input, &file_stat) == -1) {
        perror("fstat");
        exit(1);
    }

    size_t bufferSize = file_stat.st_size + 1; // Plus one for the null terminator
    void *buffer = malloc(bufferSize);
    if (!buffer) {
        perror("malloc");
        exit(1);
    }

    ssize_t bytesRead = read(fd_input, buffer, bufferSize - 1);
    if (bytesRead == -1) {
        perror("read");
        exit(1);
    }
    ((uint8_t *)buffer)[bytesRead] = '\0'; // Ensure null terminated string

    int fd_output = open(argv[2], O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd_output == -1) {
        perror("open");
        exit(1);
    }

    uint32_t checksum = calculateChecksum(buffer, bytesRead);

    if (write(fd_output, &bytesRead, sizeof(size_t)) != sizeof(size_t) ||
        write(fd_output, &checksum, sizeof(uint32_t)) != sizeof(uint32_t)) {
        perror("write");
        exit(1);
    }

    free(buffer);
    close(fd_input);
    close(fd_output);

    return 0;
}
```

This code reads a file, calculates the checksum (assuming simple addition of all bytes), and saves both the number of bytes read and the checksum to another file. The checksum is 0 if the buffer is empty.

