[' Here's a C function that accomplishes what you described. I named it `readline` for clarity, but feel free to use a more appropriate name if you prefer. This function uses an array of size 1024 (to store the input string) and a variable `count` to keep track of how many characters have been read. The newline character is skipped using the `getc()` function from the standard library after reading the input.

```c
#include <stdio.h>
#include <stdlib.h>

int readline(char* buffer, size_t size) {
    if (size <= 0) return -1; // Invalid input size
    int count = 0;
    char c;

    for (int i = 0; i < size - 1 && (c = getc(stdin)) != EOF; ++i) {
        if (c == '\n') break; // Skip newline character
        buffer[i] = c;
        count++;
    }

    if (count >= size - 1) { // Buffer was full, discard the rest of the input
        while ((c = getc(stdin)) != EOF && c != '\n')
            ;
    }
    buffer[count] = '\0'; // Null terminate the string

    if (c == EOF) return -1; // End-of-file reached during input
    else return count; // Number of characters read
}
```

