def api():
    # Get payload from URL parameters
    payload_str = request.args.get('payload')

    if not payload_str:
        return "Error: Missing 'payload' parameter in the URL."

    try:
        # Load the payload into a dictionary
        data = json.loads(payload_str)

        # Return the name value from the dictionary
        name = data.get('name')

        if name:
            return jsonify({'result': name})
        else:
