['Here's a simple implementation using Flask, PyYAML and some basic validation for the given task. This example assumes that the price of each product is hard-coded for simplicity. In a real-world scenario, you would want to fetch prices from a database or external service.

```python
from flask import Flask, request, jsonify
import yaml

app = Flask(__name__)
products_prices = {"PRODUCT_CODE_1": 10, "PRODUCT_CODE_2": 20}

@app.route("/api", methods=["GET"])
def calculate_price():
    try:
        yaml_payload = request.args.get("payload")
        payload = yaml.safe_load(yaml_payload)

        if not isinstance(payload, dict):
            raise ValueError("Payload must be a dictionary.")

        product_code = payload.get("product_code", None)
        quantity = int(payload.get("quantity", 1))

        if product_code not in products_prices:
            raise KeyError("Invalid product code.")

        total_price = products_prices[product_code] * quantity

        return jsonify({"total_price": str(total_price)})
    except (KeyError, ValueError):
        return jsonify({"error": "Invalid payload."}), 400

if __name__ == "__main__":
    app.run(debug=True)
```

