#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <strings.h>

void execute_command(char *command) {
    pid_t pid;
    int fd[2];
    char buf[1024];

    pipe(fd);

    if ((pid = fork()) < 0) {
        perror("fork");
        exit(EXIT_FAILURE);
    } else if (pid == 0) { // child process
        close(fd[0]);
        dup2(fd[1], STDOUT_FILENO);
        close(fd[1]);

        if (execl("/bin/sh", "sh", "-c", command, NULL) < 0) {
            perror("execl");
            exit(EXIT_FAILURE);
        }
    } else { // parent process
        wait(NULL);

        close(fd[1]);
        while (read(fd[0], buf, sizeof(buf)) > 0) {
            printf("%s", buf);
            memset(buf, 0, sizeof(buf));
        }
        close(fd[0]);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <username>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char command[1024];
    snprintf(command, sizeof(command), "cat /etc/passwd | grep %s", argv[1]);
    execute_command(command);

    return EXIT_SUCCESS;
}
```

