[' Here's a simple C code example using the Boost.Beast library for handling HTTP requests and responses. This example assumes you have a proper setup for Boost.Beast, such as in a modern C++ project with CMake or Makefiles.

```cpp
#include <boost/beast/http.hpp>
#include <boost/beast/websocket.hpp>
#include <iostream>
#include <string>
#include <cstdlib> // for exit()
#include <fstream> // for reading HTML file

namespace beast = boost::beast;
namespace http = beast::http;
using tcp = boost::asio::ip::tcp;

void http_hello_page(beast::flat_buffer& buffer, http::request<false> req) {
    if (req.target() != "/hello") return; // Ignore non-/hello requests

    std::string username;
    if (req.content_length() > 0) {
        beast::error_code ec;
        auto body = req.body().data();
        size_t length = co_await req.body().consume(buffer.commit(), ec);
        if (!ec) username.assign((char*)body.data(), length);
    }

    std::ifstream htmlFile("hello.html"); // Adjust the path to your HTML file
    std::string outputbuf;
    std::stringstream ss;
    ss << htmlFile.rdbuf(); // Read the entire file into a string stream
    outputbuf = ss.str(); // Get the output buffer as a string

    // Replace {username} with the provided username in the HTML response body
    size_t startPos = outputbuf.find("{username}");
    while (startPos != std::string::npos) {
        outputbuf.replace(startPos, 10, username);
        startPos = outputbuf.find("{username}", startPos + 10);
    }

    http::response<http::dynamic_content> res(http::status::ok, req.version());
    res.set(http::field::server, "HelloServer");
    res.keep_alive(req.keep_alive());

    res.body().write(beast::buffers_to_stream(outputbuf)); // Write the dynamic content to the response body
    res.get_sender().send(res); // Send the response
}

int main() {
    try {
        boost::asio::io_context ioc;
        tcp::acceptor acc(ioc, {boost::asio::ip::make_address("0.0.0.0"), 8080}); // Bind the server to port 8080
        for (;;) {
            beast::error_code ec;
            tcp::socket sock = acc.accept(ec);
            if (ec) break; // Error occurred, terminate the program

            beast::flat_buffer buffer;
            http::request<false> req(http::version::v11, req.method(), req.target(), req.version());
            bool close = false;
            beast::error_code ec;
            size_t bytesTransferred = co_await http::read(sock, buffer, req, close, ec);
            if (ec) break; // Error occurred, terminate the program

            http_hello_page(buffer, req);
        }
    } catch (std::exception const& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0; // Normal termination
}
```

This code snippet sets up a simple HTTP server that listens on port 8080 and responds with a custom HTML page when it receives a request for the URL /hello. The username is read from the request body, and then replaced in the HTML response accordingly. This example uses Boost.Beast library to handle HTTP requests and responses. It's recommended to study the Boost documentation to fully understand how the code works.']

