```python
from flask import Flask, render_template
from flask_sqlalchemy import SQLAlchemy
from os import getenv

# Initialize Flask app
app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'postgresql://{dbuser}:{dbpass}@{server}/{dbname}'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False

# Initialize SQLAlchemy database connection
db = SQLAlchemy(app)

def get_connection():
    return db.engine.connect()

def get_server():
    return app.config['SQLALCHEMY_DATABASE_URI'].split('//')[1].replace('/', '@')

def get_dbname():
    return app.config['SQLALCHEMY_DATABASE_URI'].split('/')[-1]

def get_dbuser():
    return app.config['SQLALCHEMY_DATABASE_URI'].split('//')[2].replace(':', '')

def get_dbpass():
    dburi = app.config['SQLALCHEMY_DATABASE_URI']
    dbuser, dbpass, _ = dburi.split('://')[-1].split('/')[0].split('@')
    return dbpass

@app.route('/')
def home():
    return render_template('home.html')

if __name__ == '__main__':
    app.run(debug=True)
```"]
